						actionLua = "local pref=FrogDrawMenuPreferences\nif not pref or pref.version~=3 then\n pref={version=3,permanent=false,selected=\"fru\",path=GetLuaModsPath()..[[TensorReactions\\FrogDrawMenuHostSettings.lua]]}\n local ok,saved=pcall(FileLoad,pref.path)\n if ok and type(saved)==\"table\"then pref.permanent=saved.permanent==true;pref.selected=saved.selected==\"dsr\"and\"dsr\"or\"fru\"end\n function pref.save()\n  local value={permanent=pref.permanent,selected=pref.selected}\n  local ok,err=pcall(FileSave,pref.path,value)\n  local readOK,saved=pcall(FileLoad,pref.path)\n  if not ok or not readOK or type(saved)~=\"table\"or saved.permanent~=value.permanent or saved.selected~=value.selected then pref.message=\"Save failed: \"..tostring(err);return false end\n  pref.message=nil;return true\n end\n function pref.inDuty()\n  return InInstance()\n end\n function pref.visible()\n  return pref.permanent or (TensorReactions_CurrentTimer or 0)<30\n end\n function pref.draw()\n  local permanent=GUI:Checkbox(\"Keep draws menu open during pulls\",pref.permanent)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Keep this menu visible after 30 seconds into the pull. Saves automatically.\")end\n  if permanent~=pref.permanent then pref.permanent=permanent;pref.save()end\n  if pref.message then GUI:TextUnformatted(pref.message)end\n end\n FrogDrawMenuPreferences=pref\nend\nlocal h=FrogDrawMenuHost\nif not h or h.version~=12 then\n local previous=h\n h={version=12,protocolVersion=2,lastSeen=previous and previous.lastSeen or 0,owners={},settings={}}\n if previous then\n  for _,key in ipairs({\"owners\",\"settings\",\"fruData\",\"dsrData\"})do if previous[key]~=nil then h[key]=previous[key]end end\n end\n function h.claim(game,owner)\n  if h.owners[game]==owner then return false end\n  h.owners[game]=owner;return true\n end\n function h.reloadFRU()\n  FrogFRUDrawSettings=nil\nif not FrogFRUDrawSettings or FrogFRUDrawSettings.menuVersion~=2 or FrogFRUDrawSettings.visualVersion~=30 or FrogFRUDrawSettings.p1Version~=3 or FrogFRUDrawSettings.ctMarkVersion~=1 then\n local old=FrogFRUDrawSettings\n local path=GetLuaModsPath()..[[TensorReactions\\FrogFRUDrawSettings.lua]]\n if type(old)~=\"table\" then\n  local ok,value=pcall(FileLoad,path)\n  old=ok and type(value)==\"table\" and value or {}\n end\n local p={menuVersion=2,visualVersion=30,path=path,open=true,phase=old.phase or 1,region=old.region or \"NA\",bait=old.bait or \"T1\",kb=old.kb~=false,skyKB=old.skyKB~=false,akh=old.akh or \"7-1\",ctAkh=old.ctAkh or old.akh or \"7-1\",akhSolo=old.akhSolo or \"T2\",ctSolo=old.ctSolo or (old.akhSolo==\"T1\" and \"T2\" or \"T1\"),somber=old.somber or (old.somberBoth and \"T1 both\" or \"T1 then T2\"),styles={}}\n p.calloutOutput=old.calloutOutput or \"Both\"\n p.calloutModes={\"Both\",\"Text only\",\"Sound only\",\"Off\"}\n p.ctMarkVersion=1;p.ctMarkBlue=old.ctMarkBlue==true;p.ctOwned=old.ctOwned\n p.arrowAppearance=old.arrowAppearance==\"Gradient\" and \"Gradient\" or \"Solid\"\n p.towerTank=old.towerTank==\"Stacked\" and \"Stacked\" or old.towerTank==\"OT north\" and \"OT north\" or \"MT north\"\n p.towerLightningGap=old.towerLightningGap==true;p.towerFireKB=old.towerFireKB==true\n p.p1Version=3\n p.skyStackGroups=(old.skyStackGroups==\"Roles\" or old.skyStackGroups==\"Light parties\") and old.skyStackGroups or (p.region==\"EU\" and \"Light parties\" or \"Roles\")\n p.skyTetherMode=old.skyTetherMode\n if p.skyTetherMode~=\"Fixed\" and p.skyTetherMode~=\"Light party\" and p.skyTetherMode~=\"Roles\" then\n  if old.skyFixedTether~=nil then p.skyTetherMode=old.skyFixedTether and \"Fixed\" or \"Light party\"\n  else p.skyTetherMode=p.region==\"EU\" and \"Light party\" or p.region==\"NA\" and \"Fixed\" or \"Roles\" end\n end\n p.darkCrystalCones=old.darkCrystalCones~=false\n p.regions={\"NA\",\"EU\",\"JP\",\"Elemental\"}\n p.phases={\"P1 / Fatebreaker\",\"P2 / Usurper\",\"P3 / Oracle\",\"P4 / Reunion\",\"P5 / Pandora\"}\n p.modes={\"Tether\",\"Arrow\",\"Disabled\"}\n p.formations={\"7-1\",\"4-4\",\"6-2\"}\n p.tanks={\"T1\",\"T2\"}\n p.somberChoices={\"T1 then T2\",\"T1 both\",\"T2 both\",\"T2 then T1\"}\n p.rows={{\"proteans\",\"Proteans\"},{\"sky\",\"Utopian Sky\"},{\"skyCleaves\",\"Sky cleaves\"},{\"skyStacks\",\"Sky stacks\"},{\"faith\",\"Fall of Faith\"},{\"towers\",\"Towers\"},{\"dd\",\"Diamond Dust\"},{\"mm\",\"Mirror Mirror\"},{\"lr\",\"Light Rampant\"},{ \"intermission\",\"Intermission\"},{\"ur\",\"UR\"},{\"apoc\",\"Apocalypse\"},{\"darklit\",\"Darklit\"},{\"akhRhai\",\"Akh Rhai\"},{\"somber\",\"Somber Dance\"},{\"akh1\",\"Akh Morn 1\"},{\"afah1\",\"Morn Afah 1\"},{\"ct\",\"Crystallize Time\"},{\"akh2\",\"Akh Morn 2\"},{\"afah2\",\"Morn Afah 2\"},{\"p5_fulgent\",\"Fulgent Blade\"},{\"p5_paradise\",\"Paradise / Wings\"},{\"p5_polar\",\"Polarizing Strikes\"}}\n p.groups={{\"proteans\",\"sky\",\"skyCleaves\",\"skyStacks\",\"faith\",\"towers\"},{\"dd\",\"mm\",\"lr\",\"intermission\"},{\"ur\",\"apoc\"},{\"akhRhai\",\"darklit\",\"somber\",\"akh1\",\"afah1\",\"ct\",\"akh2\",\"afah2\"},{\"p5_fulgent\",\"p5_paradise\",\"p5_polar\"}}\n p.labels={}\n for _,row in ipairs(p.rows)do\n  local key=row[1];p.labels[key]=row[2]\n  local mode=type(old.styles)==\"table\" and old.styles[key]\n  if key==\"intermission\" and mode==nil and type(old.styles)==\"table\" then mode=old.styles.lr end\n  if mode~=\"Arrow\" and mode~=\"Tether\" and mode~=\"Disabled\" then\n   local enabled=old[key]~=false\n   if key==\"apoc\" then enabled=old.mode~=\"Disabled\" end\n   if key:sub(1,3)==\"p5_\" then mode=old.p5Mode or \"Tether\";enabled=old.p5~=false end\n   mode=enabled and (mode or \"Tether\") or \"Disabled\"\n  end\n  p.styles[key]=mode\n end\n function p.styleFor(key) return p.styles[key] or \"Tether\" end\n function p.sync()\n  p.p5Strategy=p.region==\"JP\" and \"Mana\" or p.region\n  p.dd=p.styles.dd~=\"Disabled\";p.mm=p.styles.mm~=\"Disabled\";p.lr=p.styles.lr~=\"Disabled\"\n  p.skyStacks=p.styles.skyStacks~=\"Disabled\"\n  p.mode=p.styles.apoc==\"Disabled\" and \"Disabled\" or \"Tether\"\n  p.darklit=false\n  for _,key in ipairs({\"darklit\",\"akhRhai\",\"somber\",\"akh1\",\"afah1\"})do if p.styles[key]~=\"Disabled\" then p.darklit=true end end\n  p.ct=p.styles.ct~=\"Disabled\" or p.styles.akh2~=\"Disabled\" or p.styles.afah2~=\"Disabled\"\n  p.p5=p.styles.p5_fulgent~=\"Disabled\" or p.styles.p5_paradise~=\"Disabled\" or p.styles.p5_polar~=\"Disabled\"\n  p.p5Mode=\"Tether\"\n end\n function p.assignSkyStacks(s)\n if not s.safeSide or not s.rosterReady then return false end\n local short,long=s.sources[s.safeSide],s.sources[-s.safeSide]\n if not short or not long or short.target==long.target then return false end\n local prefs=FrogFRUDrawSettings or {}\n local region=prefs.region or \"NA\"\n local groups=prefs.skyStackGroups or (region==\"EU\" and \"Light parties\" or \"Roles\")\n local mode=prefs.skyTetherMode or \"Fixed\"\n local fixed=mode==\"Fixed\"\n local shortRole,longRole\n for _,key in ipairs(s.keys) do\n  local r=s.records[key]\n  local support=key:sub(1,1)==\"T\" or key:sub(1,1)==\"H\"\n  r.north=groups==\"Light parties\" and key:sub(2)==\"1\" or groups~=\"Light parties\" and support\n  r.flex=nil;r.prey=nil\n  if r.id==short.target then shortRole=key end\n  if r.id==long.target then longRole=key end\n end\n if not shortRole or not longRole then return false end\n local a,b=s.records[shortRole],s.records[longRole]\n local northRole,southRole=longRole,shortRole\n if mode==\"Roles\" then\n  local order=region==\"JP\" and {\"H1\",\"H2\",\"T1\",\"T2\",\"M1\",\"M2\",\"R1\",\"R2\"} or {\"T1\",\"T2\",\"H1\",\"H2\",\"M1\",\"M2\",\"R1\",\"R2\"}\n  local first\n  for _,key in ipairs(order) do\n   if key==shortRole or key==longRole then first=key;break end\n  end\n  local other=first==shortRole and longRole or shortRole\n  local bothSupport=(first:sub(1,1)==\"T\" or first:sub(1,1)==\"H\") and (other:sub(1,1)==\"T\" or other:sub(1,1)==\"H\")\n  northRole=region~=\"JP\" and bothSupport and other or first\n  southRole=northRole==shortRole and longRole or shortRole\n elseif mode==\"Light party\" then\n  local shortNorth=shortRole:sub(2)==\"1\"\n  local longNorth=longRole:sub(2)==\"1\"\n  if shortNorth~=longNorth then northRole=shortNorth and shortRole or longRole\n  else\n   local first\n   for _,key in ipairs({\"T1\",\"T2\",\"M1\",\"M2\",\"R1\",\"R2\",\"H1\",\"H2\"}) do if key==shortRole or key==longRole then first=key;break end end\n   if shortNorth then northRole=first==shortRole and longRole or shortRole\n   else northRole=first end\n  end\n  southRole=northRole==shortRole and longRole or shortRole\n end\n s.records[northRole].north=true;s.records[southRole].north=false\n a.prey=true;b.prey=true\n local northCount=0\n for _,key in ipairs(s.keys) do if s.records[key].north then northCount=northCount+1 end end\n if northCount~=4 then\n  local flexOrder=(mode==\"Light party\" or groups==\"Light parties\") and {\"T1\",\"T2\",\"M1\",\"M2\",\"R1\",\"R2\",\"H1\",\"H2\"} or {\"T1\",\"M1\",\"T2\",\"M2\",\"R1\",\"R2\",\"H1\",\"H2\"}\n  for _,key in ipairs(flexOrder) do\n   local r=s.records[key]\n   if not r.prey and r.north==(northCount>4) then r.north=not r.north;r.flex=true;break end\n  end\n end\n local north=0\n for _,key in ipairs(s.keys) do if s.records[key].north then north=north+1 end end\n if north~=4 then return false end\n s.northTarget=s.records[northRole].id;s.southTarget=s.records[southRole].id\n s.assignedGroups=groups;s.assignedFixed=fixed\n s.ready=true;s.dirty=false;return true\nend\n function p.clearCTMarks()\n  local pending=false\n  for marker,id in pairs(p.ctOwned or {})do\n   local actor=TensorCore.mGetEntity(id)\n   if actor and actor.marker==marker then\n    local action=ActionList:Get(12,marker)\n    if action then action:Cast(id)end\n    pending=true\n   elseif actor then p.ctOwned[marker]=nil\n   else pending=true end\n  end\n  p.ctCleanupTries=(p.ctCleanupTries or 0)+1\n  p.ctCleanupAt=pending and p.ctCleanupTries<4 and Now()+600 or nil\n  if not pending then p.ctOwned=nil end\n end\n function p.document()\n  local value={calloutOutput=p.calloutOutput,towerTank=p.towerTank,towerLightningGap=p.towerLightningGap,towerFireKB=p.towerFireKB,arrowAppearance=p.arrowAppearance,menuVersion=2,ctMarkBlue=p.ctMarkBlue,skyStackGroups=p.skyStackGroups,skyTetherMode=p.skyTetherMode,darkCrystalCones=p.darkCrystalCones,region=p.region,bait=p.bait,kb=p.kb,skyKB=p.skyKB,akh=p.akh,ctAkh=p.ctAkh,akhSolo=p.akhSolo,ctSolo=p.ctSolo,somber=p.somber,styles={}}\n  for _,row in ipairs(p.rows)do value.styles[row[1]]=p.styles[row[1]] end\n  return value\n end\n function p.callout(text)\n  local mode=p.calloutOutput or \"Both\"\n  if mode==\"Both\" or mode==\"Text only\" then TensorCore.addAlertText(2500,text,1,2,false,75) end\n  if mode==\"Both\" or mode==\"Sound only\" then TensorCore.sendTTS(text,75) end\n end\n function p.save()\n  p.sync()\n  local value=p.document()\n  local ok,result=pcall(FileSave,p.path,value)\n  if not ok or result==false then p.message=\"Save failed\";return false end\n  local readOK,saved=pcall(FileLoad,p.path)\n  if not readOK or type(saved)~=\"table\" or type(saved.styles)~=\"table\" then p.message=\"Save verification failed\";return false end\n  for key,v in pairs(value)do if key~=\"styles\" and saved[key]~=v then p.message=\"Save verification failed\";return false end end\n  for key,v in pairs(value.styles)do if saved.styles[key]~=v then p.message=\"Save verification failed\";return false end end\n  p.message=\"Saved\";return true\n end\n function p.apply(region)\n  p.towerTank=\"MT north\"\n  p.skyStackGroups=region==\"EU\" and \"Light parties\" or \"Roles\"\n  p.skyTetherMode=region==\"NA\" and \"Fixed\" or region==\"EU\" and \"Light party\" or \"Roles\"\n  p.region=region;p.akh=region==\"Elemental\" and \"4-4\" or \"7-1\";p.ctAkh=p.akh\n  p.akhSolo=region==\"JP\" and \"T1\" or \"T2\";p.ctSolo=p.akhSolo==\"T1\" and \"T2\" or \"T1\"\n  local members=AnyoneCore and AnyoneCore.Roster.members() or {}\n  local mt=members and members.T1\n  local mtPaladin=mt and mt.job==19\n  p.bait=region==\"JP\" and (mtPaladin and \"T1\" or \"T2\") or \"T1\"\n  p.somber=\"T1 then T2\"\n  if region==\"JP\" or region==\"EU\" then p.somber=mtPaladin and \"T2 both\" or \"T1 both\" end\n  if region==\"EU\" then\n   p.akhSolo=mtPaladin and \"T1\" or \"T2\"\n   p.ctSolo=mtPaladin and \"T2\" or \"T1\"\n  end\n  p.sync()\n  if p.save() then p.message=region..\" preset applied.\" end\n end\n function p.release(context,key)\n  local states=context.frog_fru_guidance_v2\n  local state=states and states[key]\n  if state and state.uuid then Argus.deleteTimedShape(state.uuid) end\n  if state and state.halo then Argus.deleteTimedShape(state.halo) end\n  if states then states[key]=nil end\n end\n function p.cleanup(context)\n  local states=context.frog_fru_guidance_v2\n  if not states then return end\n  local now=Now()\n  for key,state in pairs(states)do\n   if now-state.seen>500 or p.styleFor(state.style)~=\"Arrow\" then p.release(context,key) end\n  end\n end\n function p.markerFor(style,owner)\n  if style==\"lr\" then\n   local assignment=owner.assignments and owner.assignments[owner.role]\n   return assignment~=nil and not assignment.bait and not assignment.done\n  end\n  if style==\"mm\" then return owner.phase==\"pairs\" or owner.phase==\"spread\" end\n  if style==\"darklit\" then return owner.stage==0 or owner.stage==1 end\n  if style==\"apoc\" then return owner.stage==0 or owner.stage==3 or owner.stage==6 end\n  if style==\"ct\" then return owner.finished==true and not owner.spread and not owner.spiritDone end\n  return style==\"skyStacks\" or style==\"faith\" or style==\"towers\" or style==\"ur\" or style==\"akhRhai\" or style==\"akh1\" or style==\"akh2\" or style==\"afah1\" or style==\"afah2\"\n end\n function p.arrowDrawer(color,flags,countdown,style)\n  local drawer\n  if p.arrowAppearance==\"Gradient\" and countdown~=false then\n   local start=color\n   local mid=style and style:sub(1,3)==\"p5_\" and 0xFFD02090 or color==0xFFFF40FF and 0xFFA020FF or 0xFF0088FF\n   local finish=style and style:sub(1,3)==\"p5_\" and 0xFF4000FF or color==0xFFFF40FF and 0xFF4000FF or 0xFF0000FF\n   drawer=TensorCore.getCachedDrawer(start,mid,finish,0xFFFFFFFF,2,0,flags)\n  else\n   drawer=TensorCore.getCachedDrawer(color,color,color,0xFFFFFFFF,2,0,flags)\n  end\n  drawer.gradientMinOpacity=0.6\n  return drawer\n end\n function p.castDeadline(context,owner,ids)\n  local times=context.frog_fru_arrow_casts\n  if not times then return end\n  local floor=owner.start or owner.started or 0\n  local deadline\n  for _,id in ipairs(ids)do\n   local cast=times[id]\n   if cast and cast.at>=floor and cast.at<=Now() then\n    deadline=deadline and math.min(deadline,cast.deadline) or cast.deadline\n   end\n  end\n  return deadline\n end\n function p.guide(context,key,style,owner,player,x,y,z,label,ttl,width)\n  local mode=p.styleFor(style)\n  if mode==\"Arrow\" then y=0 end\n  if mode==\"Disabled\" then p.release(context,key);return end\n  local flags=Argus2.RenderFlags.FLAG_RENDER_OVERLAY+Argus2.RenderFlags.FLAG_WARP_TERRAIN\n  local distance=(player.pos.x-x)^2+(player.pos.z-z)^2\n  local arrival=(owner.arrivalRadius or .8)^2\n  local drawer=TensorCore.getStaticDrawer(distance<=arrival and 0xFF40E080 or 0xFF00FFFF,1,0,flags)\n  if mode==\"Arrow\" then\n   local color=style:sub(1,3)==\"p5_\" and 0xFF40FF40 or style==\"ur\" and 0xFFFF40FF or 0xFF00FFFF\n   local holding=owner.arrowHoldAfterDeadline and owner.arrowDeadline and Now()>=owner.arrowDeadline\n   if holding then color=style:sub(1,3)==\"p5_\" and 0xFF4000FF or style==\"ur\" and 0xFFFF0080 or 0xFF0000FF end\n   drawer=p.arrowDrawer(color,flags,owner.arrowDeadline~=nil and not holding,style)\n  end\n  if mode==\"Tether\" and p.markerFor(style,owner) then drawer:addCircle(x,y,z,.6,false,flags) end\n  if mode==\"Tether\" then\n   p.release(context,key)\n   if distance>arrival then drawer:addLine(player.pos.x,player.pos.y+.07,player.pos.z,x,y,z,width or 6,2)\n   elseif owner.keepVisible then\n    local h=owner.heading or 0\n    drawer:addLine(x-math.sin(h)*2,y,z-math.cos(h)*2,x,y,z,width or 6,2)\n   end\n   return\n  end\n  local states=context.frog_fru_guidance_v2\n  if not states then states={};context.frog_fru_guidance_v2=states end\n  local now=Now();local holding=owner.arrowHoldAfterDeadline and owner.arrowDeadline and now>=owner.arrowDeadline\n  local stage=tostring(p.arrowAppearance)..\":\"..tostring(owner.arrowStage or owner.stage or owner.phase or owner.step or owner.nextHit or \"\")..\":\"..tostring(label or \"\")..\":\"..tostring(owner.arrowDeadline or \"\")..\":\"..tostring(holding)\n  local state=states[key]\n  local anchor=state and state.owner==owner and state.label==label and state.style==style and now>=state.seen and {x=state.x,y=state.y,z=state.z} or nil\n  if state and (state.owner~=owner or state.stage~=stage or now<state.seen) then p.release(context,key);state=nil end\n  if distance<=arrival and not owner.keepVisible then\n   if state and state.uuid then Argus.deleteTimedShape(state.uuid);state.uuid=nil end\n   if not state then state={owner=owner,stage=stage,style=style};states[key]=state end\n   state.arrived=true;state.tx=x;state.tz=z;state.seen=now;return\n  end\n  if state and state.arrived then\n   if (state.tx or x)-x==0 and (state.tz or z)-z==0 then state.seen=now;return end\n   p.release(context,key);state=nil\n  end\n  local ox,oy,oz=player.pos.x,player.pos.y+.08,player.pos.z\n  if not state and owner.keepVisible and distance<=arrival then\n   local h=owner.heading or 0\n   ox=x-math.sin(h)*2;oy=y;oz=z-math.cos(h)*2\n  end\n  if state then ox,oy,oz=state.x,state.y,state.z elseif anchor then ox,oy,oz=anchor.x,anchor.y,anchor.z end\n  if owner.arrowFromCenter or style==\"faith\" or style==\"sky\" or style==\"towers\" or (style==\"skyStacks\" and not state and not anchor) then ox=100;oy=y;oz=100 end\n  if style==\"intermission\" and owner.crystalOrigin then ox=owner.crystalOrigin.x;oz=owner.crystalOrigin.z end\n  oy=y\n  local dx,dz=x-ox,z-oz;local length=math.sqrt(dx*dx+dz*dz)\n  if length<4 then\n   local h=length>.05 and math.atan2(dx,dz) or owner.heading or math.atan2(x-100,z-100)\n   ox=x-math.sin(h)*4;oy=y;oz=z-math.cos(h)*4\n   dx=x-ox;dz=z-oz;length=4\n  end\n  if length<.05 then return end\n  local tip=math.min(2,length*.35);local heading=math.atan2(dx,dz)\n  local deadline=owner.arrowDeadline\n  if deadline and now>=deadline and not holding then p.release(context,key);return end\n  local duration=deadline and not holding and math.max(1,deadline-now) or 180000\n  local haloDrawer\n  if style:sub(1,3)==\"p5_\" then haloDrawer=TensorCore.getCachedDrawer(0,0,0,0xFF101010,6,0,flags) end\n  if state and ((state.tx-x)^2+(state.tz-z)^2>.0625 or (state.x-ox)^2+(state.y-oy)^2+(state.z-oz)^2>.0001) then\n   if state.halo and not haloDrawer:updateTimedArrow(state.halo,nil,ox,oy,oz,heading,length-tip,.75,tip,1.5,0,false,flags) then p.release(context,key);state=nil end\n   if state and not drawer:updateTimedArrow(state.uuid,nil,ox,oy,oz,heading,length-tip,.75,tip,1.5,0,false,flags) then p.release(context,key);state=nil end\n   if state then state.refreshed=now;state.tx=x;state.tz=z;state.x=ox;state.y=oy;state.z=oz end\n  end\n  if not state then\n   local halo=haloDrawer and haloDrawer:addTimedArrow(duration,ox,oy,oz,heading,length-tip,.75,tip,1.5,0,false,flags)\n   local uuid=drawer:addTimedArrow(duration,ox,oy,oz,heading,length-tip,.75,tip,1.5,0,false,flags)\n   if not uuid then if halo then Argus.deleteTimedShape(halo) end;return end\n   state={uuid=uuid,halo=halo,owner=owner,stage=stage,style=style,label=label,x=ox,y=oy,z=oz,tx=x,tz=z,refreshed=now};states[key]=state\n  end\n  state.seen=now\n end\n function p.drawSpreads(owner,style)\n  if p.styleFor(style)==\"Disabled\" then return end\n  local flags=Argus2.RenderFlags.FLAG_WARP_TERRAIN\n  if not p.spreadDrawer then p.spreadDrawer=TensorCore.getCachedDrawer(0x300040FF,nil,0x300040FF,0xD06080FF,2,0,flags) end\n  for _,key in ipairs(owner.keys)do\n   local record=owner.records[key]\n   local actor=record and TensorCore.mGetEntity(record.id)\n   if actor and actor.pos and actor.hp.current>0 then\n    p.spreadDrawer:addCircle(actor.pos.x,actor.pos.y+.04,actor.pos.z,5,false,flags)\n   end\n  end\n end\n p.sync();p.presetChoice=1\n for i,region in ipairs(p.regions)do if p.region==region then p.presetChoice=i end end\n FrogFRUDrawSettings=p\nend\nlocal p=FrogFRUDrawSettings\nif p.skyKBVersion~=1 then\n local allowed={\n  [25]={[155]=1}, \n  [24]={[37008]=1}, \n  [38]={[16010]=1}, \n  [41]={[34646]=1}, \n  [20]={[25762]=1}, \n  [39]={[24401]=1,[24402]=2}, \n  [22]={[94]=1}, \n  [40]={[24295]=1}, \n  [30]={[2262]=1}, \n }\n function p.skyKBCancel(player)\n  if p.skyKB~=true or not player then return end\n  local jobActions=allowed[player.job];if not jobActions then return end\n  local selected,rank,name\n  for _,t in pairs(TensorCore.API.TensorACR.getHotbarToggles() or {})do\n   local n=type(t.name)==\"function\" and t.name() or t.name\n   local r=jobActions[t.id]\n   if t.enabled~=false and r and type(n)==\"string\" and n:find(\"KB Cancel\",1,true) and type(t.var)==\"string\"then\n    if not selected or r<rank or (r==rank and n<name)then selected,rank,name=t,r,n end\n   end\n  end\n  return selected\n end\n p.skyKBVersion=1\nend\nif p.banishVersion~=1 then\n function p.drawBanish(kind,deadline,style)\n  if (kind~=\"pairs\" and kind~=\"spread\") or not deadline or Now()>deadline+700 or p.styleFor(style)==\"Disabled\" then return end\n  if not AnyoneCore or not AnyoneCore.Roster.isReady() then return end\n  local flags=Argus2.RenderFlags.FLAG_WARP_TERRAIN\n  if not p.spreadDrawer then p.spreadDrawer=TensorCore.getCachedDrawer(0x300040FF,nil,0x300040FF,0xD06080FF,2,0,flags) end\n  if not p.banishStackDrawer then p.banishStackDrawer=TensorCore.getCachedDrawer(0x3040E080,nil,0x3040E080,0xD040E080,2,0,flags) end\n  local keys=kind==\"pairs\" and {\"T1\",\"T2\",\"H1\",\"H2\"} or {\"T1\",\"T2\",\"H1\",\"H2\",\"M1\",\"M2\",\"R1\",\"R2\"}\n  local drawer=kind==\"pairs\" and p.banishStackDrawer or p.spreadDrawer\n  for _,key in ipairs(keys)do\n   local id=AnyoneCore.Roster.idOf(key)\n   local actor=id and TensorCore.mGetEntity(id)\n   if actor and actor.pos and actor.hp.current>0 then drawer:addCircle(actor.pos.x,actor.pos.y+.04,actor.pos.z,5,false,flags) end\n  end\n end\n p.banishVersion=1\nend\n\n end\n function h.renderFRU(context)\n  local timelineMenu=false\n  local data=context\n  local self={}\n  local p=FrogFRUDrawSettings\n  if p then p.open=true end\nlocal p=FrogFRUDrawSettings\nif not p or p.menuVersion~=2 then self.used=true return end\nif not p.somberChoices or p.somberChoices[4]~=\"T2 then T1\" then p.somberChoices={\"T1 then T2\",\"T1 both\",\"T2 both\",\"T2 then T1\"} end\nif not p.p1UiReady then\n if not p.p1Version then\n  p.skyStackGroups=p.region==\"EU\" and \"Light parties\" or \"Roles\"\n  p.skyTetherMode=p.region==\"EU\" and \"Light party\" or p.region==\"NA\" and \"Fixed\" or \"Roles\"\n end\n p.p1UiReady=true\nend\nif not p.ui or p.ui.version~=7 then\n local ui={version=7,scopes={\"This phase\",\"All phases\"},tankLabels={\"MT\",\"OT\"},somberLabels={\"MT then OT\",\"MT both\",\"OT both\",\"OT then MT\"}}\n ui.colors={{\"Text\",.91,.92,.90,1},{\"WindowBg\",.11,.11,.11,1},{\"Border\",.29,.31,.28,1},{\"TitleBg\",.13,.13,.13,1},{\"TitleBgActive\",.15,.15,.15,1},{\"FrameBg\",.18,.19,.18,1},{\"FrameBgHovered\",.23,.28,.23,1},{\"FrameBgActive\",.23,.32,.24,1},{\"Header\",.21,.23,.21,1},{\"HeaderHovered\",.23,.32,.23,1},{\"HeaderActive\",.29,.40,.28,1},{\"CheckMark\",.56,.76,.49,1},{\"Button\",.21,.23,.21,1},{\"ButtonHovered\",.29,.31,.28,1},{\"ButtonActive\",.34,.37,.32,1}}\n function ui.push()\n  for _,c in ipairs(ui.colors)do GUI:PushStyleColor(GUI[\"Col_\"..c[1]],c[2],c[3],c[4],c[5])end\n  GUI:PushStyleVar(GUI.StyleVar_WindowRounding,0)\n  GUI:PushStyleVar(GUI.StyleVar_FrameRounding,0)\n  GUI:PushStyleVar(GUI.StyleVar_FrameBorderSize,1)\n  GUI:PushStyleVar(GUI.StyleVar_FramePadding,5*ui.scale,3*ui.scale)\n  GUI:PushStyleVar(GUI.StyleVar_ItemSpacing,6*ui.scale,6*ui.scale)\n end\n function ui.pop() GUI:PopStyleVar(5);GUI:PopStyleColor(#ui.colors) end\n function ui.label(text)\n  GUI:AlignFirstTextHeightToWidgets();GUI:TextUnformatted(text);GUI:SameLine(ui.column)\n end\n function ui.combo(label,id,index,items,width)\n  ui.label(label)\n  GUI:PushItemWidth(width or ui.width)\n  local nextIndex=GUI:Combo(\"##fru.\"..id,index,items)\n  GUI:PopItemWidth()\n  return nextIndex\n end\n function ui.check(label,id,value)\n  ui.label(label)\n  local nextValue=GUI:Checkbox(\"##fru.\"..id,value)\n  if nextValue~=value then p.message=\"Unsaved changes\" end\n  return nextValue\n end\n function ui.sharedMode()\n  local common\n  if p.quickStyleScope==2 then\n   for _,row in ipairs(p.rows)do local value=p.styles[row[1]];if common and common~=value then return nil end;common=value end\n  else\n   for _,key in ipairs(p.groups[p.phase])do local value=p.styles[key];if common and common~=value then return nil end;common=value end\n  end\n  return common\n end\n p.ui=ui\nend\nlocal ui=p.ui\nui.scale=math.max(1,GUI:GetWindowFontSize()/14)\nui.column=146*ui.scale;ui.width=246*ui.scale\np.quickStyleScope=p.quickStyleScope or 1\nGUI:SetNextWindowSize(410*ui.scale,470*ui.scale,GUI.SetCond_FirstUseEver)\nui.push()\nlocal visible=GUI:Begin(\"Frog / FRU Draws\",nil,GUI.WindowFlags_AlwaysAutoResize)\nif visible then\n if timelineMenu then pref.draw();GUI:Separator()end\n p.phase=ui.combo(\"Phase\",\"phase\",p.phase,p.phases)\n p.presetChoice=ui.combo(\"Preset\",\"preset\",p.presetChoice,p.regions,174*ui.scale)\n if GUI:IsItemHovered()then GUI:SetTooltip(\"Regional assignments and Akh Morn defaults.\")end\n GUI:SameLine(ui.column+180*ui.scale)\n if GUI:Button(\"Apply##fru.preset\",66*ui.scale,22*ui.scale)then p.apply(p.regions[p.presetChoice])end\n if GUI:IsItemHovered()then GUI:SetTooltip(\"Apply preset changes between pulls.\")end\n GUI:PushStyleColor(GUI.Col_Text,.62,.69,.61,1)\n GUI:TextUnformatted(\"Active preset: \"..p.region)\n GUI:PopStyleColor(1)\n GUI:Separator()\n if GUI:Button(\"Open AnyoneCore roster\") then\n  local popup=AnyoneCore and AnyoneCore.RosterPopup\n  if popup and type(popup.openManual)==\"function\" then\n   local ok,err=pcall(popup.openManual)\n   if not ok then p.message=\"Roster could not open: \"..tostring(err) end\n  else p.message=\"AnyoneCore roster is unavailable\" end\n end\n GUI:Separator()\n ui.label(\"Quick style\")\n local common=ui.sharedMode()\n for i,mode in ipairs(p.modes)do\n  if i>1 then GUI:SameLine(ui.column+(i-1)*84*ui.scale)end\n  local selected=common==mode\n  if selected then GUI:PushStyleColor(GUI.Col_Button,.29,.40,.28,1)end\n  local pressed=GUI:Button(mode..\"##quick_style\",78*ui.scale,22*ui.scale)\n  if GUI:IsItemHovered()then GUI:SetTooltip(mode==\"Tether\" and \"Follows you to the current mechanic destination.\" or mode==\"Arrow\" and \"Timed arrow to the next mechanic destination.\" or \"Hides guidance for the selected scope.\")end\n  if selected then GUI:PopStyleColor(1)end\n  if pressed then\n   if p.quickStyleScope==2 then\n    for _,row in ipairs(p.rows)do p.styles[row[1]]=mode end\n   else\n    for _,key in ipairs(p.groups[p.phase])do p.styles[key]=mode end\n   end\n   p.sync();p.message=(p.quickStyleScope==2 and \"All phases: \" or \"This phase: \")..mode..\" / unsaved\"\n  end\n end\n local arrowVisible=false\n if p.quickStyleScope==2 then\n  for _,row in ipairs(p.rows)do if p.styles[row[1]]==\"Arrow\"then arrowVisible=true;break end end\n else\n  for _,key in ipairs(p.groups[p.phase])do if p.styles[key]==\"Arrow\"then arrowVisible=true;break end end\n end\n if arrowVisible then\n  local appearanceItems={\"Solid\",\"Gradient\"}\n  local appearance=appearanceItems[ui.combo(\"Arrow appearance\",\"arrow_appearance\",p.arrowAppearance==\"Gradient\" and 2 or 1,appearanceItems)] or \"Solid\"\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Solid fill or a colour gradient. Applies to all FRU arrows.\")end\n  if appearance~=p.arrowAppearance then p.arrowAppearance=appearance;p.message=\"Unsaved changes\" end\n end\n p.quickStyleScope=ui.combo(\"Style scope\",\"style_scope\",p.quickStyleScope,ui.scopes)\n p.calloutModes=p.calloutModes or {\"Both\",\"Text only\",\"Sound only\",\"Off\"}\n local calloutIndex=1\n for i,mode in ipairs(p.calloutModes)do if mode==p.calloutOutput then calloutIndex=i end end\n local callout=p.calloutModes[ui.combo(\"Callouts\",\"callouts\",calloutIndex,p.calloutModes)]\n if GUI:IsItemHovered()then GUI:SetTooltip(\"Our callouts: text, voice, both or off.\")end\n if callout~=p.calloutOutput then p.calloutOutput=callout;p.message=\"Unsaved changes\"end\n GUI:Separator()\n if GUI:CollapsingHeader(\"Individual mechanic styles##fru.\"..p.phase)then\n for _,key in ipairs(p.groups[p.phase])do\n  local index=1\n  for i,mode in ipairs(p.modes)do if p.styles[key]==mode then index=i end end\n  local selected=ui.combo(p.labels[key],\"style.\"..key,index,p.modes)\n  if GUI:IsItemHovered()then GUI:SetTooltip(p.modes[selected]==\"Tether\" and \"Live tether to your assigned destination.\" or p.modes[selected]==\"Arrow\" and \"Timed arrow for each movement step.\" or \"Hides this mechanic guidance.\")end\n  if p.styles[key]~=p.modes[selected]then p.styles[key]=p.modes[selected];p.sync();p.message=\"Unsaved changes\"end\n end\n GUI:Spacing()\n GUI:Separator()\n GUI:Spacing()\n end\n if p.phase==1 then\n  local groupItems={\"Roles\",\"Light parties\"}\n  local groupIndex=ui.combo(\"Stack groups\",\"sky_stack_groups\",p.skyStackGroups==\"Light parties\" and 2 or 1,groupItems)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Roles: supports north / DPS south. Light party: G1 north / G2 south.\")end\n  local groups=groupItems[groupIndex]\n  local modes={\"Fixed\",\"Light party\",\"Roles\"}\n  local current=p.skyTetherMode==\"Roles\" and 3 or p.skyTetherMode==\"Light party\" and 2 or 1\n  local mode=modes[ui.combo(\"Tether assignment\",\"sky_fixed_tether\",current,modes)] or modes[current]\n  if GUI:IsItemHovered()then\n   local hint=mode==\"Fixed\" and \"Short tether south; other tether north.\" or mode==\"Light party\" and \"G1 north / G2 south. Flex: T > M > R > H.\" or p.region==\"JP\" and \"Marked priority north to south: H1 H2 MT OT M1 M2 R1 R2.\" or \"Supports north / DPS south; marked players split by role priority.\"\n   GUI:SetTooltip(hint)\n  end\n  if groups~=p.skyStackGroups or mode~=p.skyTetherMode then\n   p.skyStackGroups=groups;p.skyTetherMode=mode;p.message=\"Unsaved changes\"\n   local state=data.frog_fru_sky_prey\n   if state then\n    state.ready=false;state.dirty=true;state.nextPoll=0;state.destination=nil\n    if p.release then p.release(data,\"frog_fru_sky_prey\")end\n    if state.poll and p.assignSkyStacks then\n     state.assign=function()return p.assignSkyStacks(state)end\n     state.assignmentVersion=3;state.poll()\n    end\n   end\n  end\n  p.skyKB=ui.check(\"Utopian KB Cancel\",\"sky_kb\",p.skyKB)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Queues KB cancel for the Utopian fire knockback just before stacks.\")end\n local towerPlayer=TensorCore.mGetPlayer()\n if towerPlayer and (towerPlayer.job==19 or towerPlayer.job==21 or towerPlayer.job==32 or towerPlayer.job==37) then\n  GUI:Separator()\n  local choices={\"Stacked\",\"MT north\",\"OT north\"}\n  local current=p.towerTank==\"Stacked\" and 1 or p.towerTank==\"OT north\" and 3 or 2\n  local choice=choices[ui.combo(\"Tower tanks\",\"tower_tanks\",current,choices)] or choices[current]\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Opposite the towers. Stacked stays together. Split tanks wait at the wall through the buster; movement helpers are off.\")end\n  if choice~=p.towerTank then p.towerTank=choice;p.message=\"Unsaved changes\";local state=data.frog_fru_towers;if state and state.update then state.update()end end\n  if p.towerTank==\"Stacked\" then\n  p.towerLightningGap=ui.check(\"Lightning gap close\",\"tower_lightning_gap\",p.towerLightningGap==true)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Uses your tank gap closer after Burnout resolves.\")end\n  p.towerFireKB=ui.check(\"Fire KB cancel\",\"tower_fire_kb\",p.towerFireKB==true)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Queues the ACR gap-closer KB cancel 0.5s before Blastburn.\")end\n  end\n end\n elseif p.phase==2 then\n  p.darkCrystalCones=ui.check(\"Dark crystal cones\",\"dark_crystal_cones\",p.darkCrystalCones)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Shows dark-crystal cone baits and locked directions.\")end\n elseif p.phase==3 then\n  local role=ui.combo(\"Dance bait\",\"dance_bait\",p.bait==\"T2\" and 2 or 1,ui.tankLabels)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Designated tank for the Darkest Dance jump bait.\")end\n  if p.bait~=p.tanks[role]then p.bait=p.tanks[role];p.message=\"Unsaved changes\"end\n  p.kb=ui.check(\"Dance KB Cancel\",\"movement_kb\",p.kb)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Queues a supported gap-closer KB cancel 0.5s before the knockback.\")end\n elseif p.phase==4 then\n  local index=p.somber==\"T1 both\" and 2 or p.somber==\"T2 both\" and 3 or p.somber==\"T2 then T1\" and 4 or 1\n  local somber=ui.combo(\"Somber baits\",\"somber\",index,ui.somberLabels)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"First tank baits far; second baits close. Both assigns one tank to both hits.\")end\n  if p.somber~=p.somberChoices[somber]then p.somber=p.somberChoices[somber];p.message=\"Unsaved changes\"end\n  if p.region==\"JP\" then\n   p.ctMarkBlue=ui.check(\"CT blue auto marks\",\"ct_blue_marks\",p.ctMarkBlue==true)\n   if GUI:IsItemHovered()then GUI:SetTooltip(\"Attack 1-4: H1 > MT > OT > M1 > M2 > R1 > R2 > H2. Only one party member should enable this. Marks placed here clear on wipe.\")end\n  end\n  GUI:Separator()\n  local first=ui.combo(\"Akh Morn 1\",\"akh1_setup\",p.akh==\"6-2\" and 3 or p.akh==\"4-4\" and 2 or 1,p.formations)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"First Akh Morn: 7-1 solo, 4-4 light parties, or 6-2 tanks together.\")end\n  if p.akh~=p.formations[first]then p.akh=p.formations[first];p.message=\"Unsaved changes\"end\n  if p.akh==\"7-1\" then\n   local tank=ui.combo(\"AM1 Solo Tank\",\"akh1_solo\",p.akhSolo==\"T1\" and 1 or 2,ui.tankLabels)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Tank taking the first Akh Morn alone.\")end\n   if p.akhSolo~=p.tanks[tank]then p.akhSolo=p.tanks[tank];p.message=\"Unsaved changes\"end\n  end\n  local second=ui.combo(\"Akh Morn 2\",\"akh2_setup\",p.ctAkh==\"6-2\" and 3 or p.ctAkh==\"4-4\" and 2 or 1,p.formations)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Second Akh Morn after CT: solo, light parties, or tanks together.\")end\n  if p.ctAkh~=p.formations[second]then p.ctAkh=p.formations[second];p.message=\"Unsaved changes\"end\n  if p.ctAkh==\"7-1\" then\n   local tank=ui.combo(\"AM2 Solo Tank\",\"akh2_solo\",p.ctSolo==\"T1\" and 1 or 2,ui.tankLabels)\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Tank taking the second Akh Morn alone.\")end\n   if p.ctSolo~=p.tanks[tank]then p.ctSolo=p.tanks[tank];p.message=\"Unsaved changes\"end\n  end\n\n end\n GUI:Separator()\n if GUI:Button(\"Save settings\",118*ui.scale,24*ui.scale)then p.save()end\n if p.message then GUI:TextWrapped(p.message)end\nend\nGUI:End()\nui.pop()\nself.used=true\n\n end\n function h.renderDSR(context)\n  local timelineMenu=false\n  local data=context\n  local self={}\nif data.frog_draw_settings == nil or data.frog_draw_settings.version~=48 then\n local p={\n  version=48,\n  path=GetLuaModsPath() .. [[TensorReactions\\FrogDrawsSettings.lua]],\n  default=\"R1 H1 M1 MT OT M2 H2 R2\",\n  styleItems={\"Tether\",\"Arrow\",\"Disabled\"},\n  brightCones=true,brightSide=\"Roster\",skyblindMode=\"Personal\",\n  styleRows={\n   {\"p1_playstation\",\"P1 PlayStation\"},{\"p1_brightwing\",\"Vault & Rewind cleaves\"},{\"p2_strength\",\"P2 Strength\"},\n   {\"p2_sanctity\",\"P2 Sanctity\"},{\"p3_dfg\",\"P3 Dive from Grace\"},{\"p3_enum\",\"P3 Enumeration\"},\n   {\"p4_eyes\",\"P4 Eyes\"},{\"p5_wrath\",\"P5 Wrath\"},{\"p5_doth\",\"P5 DOTH\"},{\"p6_vow\",\"P6 Mortal Vow\"},{\"p6_hw_party\",\"P6 Wings party\"},{\"p6_hw_tank\",\"P6 Wings tank\"},{\"p6_wb1\",\"P6 Wyrmsbreath 1\"},{\"p6_wb2\",\"P6 Wyrmsbreath 2\"},{\"p6_cauterize\",\"P6 Double Cauterize\"},\n   {\"p7_trinity\",\"P7 Trinity\"},{\"p7_akh\",\"P7 Akh Morn\"},{\"p7_giga\",\"P7 Gigaflare\"}\n  },\n  styles={},\n  wb1Anchors={\"H1\",\"M1\",\"H2\"},wb1Flex={\"R1\",\"M2\",\"R2\"},\n  wb2Default=\"H1 R1 M1 M2 H2 R2\",wb2Edit=\"H1 R1 M1 M2 H2 R2\",\n  wb1Roles={\"H1\",\"H2\",\"M1\",\"M2\",\"R1\",\"R2\"},wb2R1North=false,\n  cautMT=\"Nidhogg\",\n  cautItems={\"Nidhogg\",\"Hraesvelgr\",\"Fixed West\",\"Fixed East\"},\n  cautOpposite={\"Hraesvelgr\",\"Nidhogg\",\"Fixed East\",\"Fixed West\"},\n  autoOrderDefault=\"M R H\",\n  autoOrderEdit=\"M R H\",\n  elementDraws=true,\n  akhStrategy=\"6-1-1\",\n  akhStrategyItems={\"6-1-1\",\"3-3-2\"},\n  autoMode=\"Personal\",\n  autoModeItems={\"Personal\",\"Shotcaller\",\"Disabled\"},\n  dothMode=\"Configured conga\",\n  dothModeItems={\"Configured conga\",\"Live positions\"},\n  akhAfahHP=false,dragonHP=true,\n  vowTTSMode=\"Personal\",\n  vowDefault=\"T T M R\",\n  vowEdit=\"T T M R\",\n  vowGroups={T={\"MT\",\"OT\"},M={\"M1\",\"M2\"},R={\"R1\",\"R2\"}},\n  strategyItems={\"Westhogg\",\"Easthogg\"},\n  strategy=\"NAUR\",\n  eyesStrategy=\"Square\",region=\"NA\",\n  holdItems={\"On\",\"Off\"},\n  customHold=false,\n  roles={MT=true,OT=true,H1=true,H2=true,M1=true,M2=true,R1=true,R2=true}\n }\n function p.parse(text)\n  if type(text)~=\"string\" then return nil,\"Enter all eight roles.\" end\n  local order,seen={},{}\n  for role in string.upper(text):gmatch(\"[^%s,]+\") do\n   if not p.roles[role] then return nil,\"Unknown role: \"..role end\n   if seen[role] then return nil,\"Duplicate role: \"..role end\n   seen[role]=true; order[#order+1]=role\n  end\n  if #order~=8 then return nil,\"Enter each of MT OT H1 H2 M1 M2 R1 R2 once.\" end\n  return order,table.concat(order,\" \")\n end\n function p.parseVow(text)\n  local order={}\n  for token in string.upper(text or \"\"):gmatch(\"[^%s,]+\") do\n   if not p.vowGroups[token] then return nil,\"Vow order uses T, M or R. Healers cannot receive.\" end\n   order[#order+1]=token\n  end\n  if #order~=4 then return nil,\"Enter four Vow passes.\" end\n  for _,initial in ipairs({\"M1\",\"M2\",\"R1\",\"R2\"}) do\n   local used={[initial]=true}\n   for _,token in ipairs(order) do\n    local chosen\n    for _,role in ipairs(p.vowGroups[token]) do\n     if not used[role] then chosen=role; break end\n    end\n    if not chosen then return nil,\"Vow order runs out of eligible receivers.\" end\n    used[chosen]=true\n   end\n  end\n  return order,table.concat(order,\" \")\n end\n function p.parseAuto(text)\n  if type(text)~=\"string\" then return nil,\"Auto order uses M, R and H once each.\" end\n  local compact=string.upper(text):gsub(\"[%s,]\",\"\")\n  if #compact~=3 then return nil,\"Enter M, R and H once each.\" end\n  local order,seen={},{}\n  for token in compact:gmatch(\".\") do\n   if token~=\"M\" and token~=\"R\" and token~=\"H\" then return nil,\"Auto order only accepts M, R and H.\" end\n   if seen[token] then return nil,\"Duplicate auto role: \"..token end\n   seen[token]=true; order[#order+1]=token\n  end\n  return order,table.concat(order,\" \")\n end\n function p.validatePairs(text)\n  local roles,seen={},{}\n  for role in (text or \"\"):gmatch(\"%S+\") do\n   if not (role==\"H1\" or role==\"H2\" or role==\"M1\" or role==\"M2\" or role==\"R1\" or role==\"R2\") or seen[role] then return nil,\"Each WB1 role must appear once.\" end\n   seen[role]=true;roles[#roles+1]=role\n  end\n  if #roles~=6 then return nil,\"Assign three anchor/flex pairs.\" end\n  return roles\n end\n function p.lineupPoints(roles)\n  local roster=AnyoneCore and AnyoneCore.Roster\n  if not roster or not roster.isReady() then return nil,\"Set the AnyoneCore roster first.\" end\n  local members=roster.members();local party=AnyoneCore.API.getAgnosticPartyList()\n  if type(members)~=\"table\" or type(party)~=\"table\" then return nil,\"Party roster unavailable.\" end\n  local slots={MT=\"T1\",OT=\"T2\",H1=\"H1\",H2=\"H2\",M1=\"M1\",M2=\"M2\",R1=\"R1\",R2=\"R2\"}\n  local points,used={},{}\n  local cx,cz=0,0\n  for _,role in ipairs(roles)do\n   local member=members[slots[role]]\n   if not member then return nil,\"Missing roster role: \"..role end\n   local candidate,count=nil,0\n   for _,a in pairs(party)do\n    if a.name==member.name and a.job==member.job then candidate=a;count=count+1 end\n   end\n   if count==0 then\n    local sameJob=0;for _,m in pairs(members)do if m.job==member.job then sameJob=sameJob+1 end end\n    if sameJob==1 then for _,a in pairs(party)do if a.job==member.job then candidate=a;count=count+1 end end end\n   end\n   if count~=1 or used[candidate.id] then return nil,\"Cannot uniquely match \"..role..\" to the party.\" end\n   local actor=TensorCore.mGetEntity(candidate.id)\n   if not actor or not actor.alive then return nil,\"All lineup players must be present and alive.\" end\n   used[actor.id]=true\n   points[#points+1]={role=role,x=actor.pos.x,z=actor.pos.z};cx=cx+actor.pos.x;cz=cz+actor.pos.z\n  end\n  return points\n end\n function p.captureLineup(roles)\n  local points,message=p.lineupPoints(roles)\n  if not points then return nil,message end\n  local cx,cz=0,0\n  for _,v in ipairs(points)do cx=cx+v.x;cz=cz+v.z end\n  cx=cx/#points;cz=cz/#points\n  local xx,xz,zz=0,0,0\n  for _,v in ipairs(points)do local x,z=v.x-cx,v.z-cz;xx=xx+x*x;xz=xz+x*z;zz=zz+z*z end\n  local h=0.5*math.atan2(2*xz,xx-zz)\n  local ux,uz=math.cos(h),math.sin(h)\n  local eastWest=math.abs(ux)>=math.abs(uz)\n  if (eastWest and ux<0) or (not eastWest and uz<0)then ux=-ux;uz=-uz end\n  local width=0\n  for _,v in ipairs(points)do\n   v.rank=(v.x-cx)*ux+(v.z-cz)*uz\n   width=math.max(width,math.abs((v.x-cx)*uz-(v.z-cz)*ux))\n  end\n  table.sort(points,function(a,b)return a.rank<b.rank end)\n  if width>3 then return nil,\"Form a single lineup before capturing.\" end\n  local order={}\n  for i,v in ipairs(points)do\n   if i>1 and v.rank-points[i-1].rank<0.3 then return nil,\"Lineup overlaps; separate the players or drag the boxes.\" end\n   order[i]=v.role\n  end\n  return order,eastWest and \"Captured W to E. Reverse if needed.\" or \"Captured N to S. Reverse if needed.\"\n end\n function p.captureDOTH()\n  local points,message=p.lineupPoints({\"MT\",\"OT\",\"H1\",\"H2\",\"M1\",\"M2\",\"R1\",\"R2\"})\n  if not points then return nil,message end\n  table.sort(points,function(a,b)return a.x<b.x end)\n  local order={}\n  for i,v in ipairs(points)do\n   if i>1 and v.x-points[i-1].x<0.3 then return nil,\"Separate players west to east before capturing DOTH.\" end\n   order[i]=v.role\n  end\n  return order,\"Captured DOTH west to east.\"\n end\n function p.captureWB1()\n  local points,message=p.lineupPoints(p.wb1Roles)\n  if not points then return nil,message end\n  local marks={}\n  for i=1,8 do\n   local x,y,z,active=Argus.getWaymarkInfo(i)\n   if active then\n    local near={}\n    for _,v in ipairs(points)do near[#near+1]={role=v.role,d=(v.x-x)^2+(v.z-z)^2}end\n    table.sort(near,function(a,b)return a.d<b.d end)\n    if near[2].d<=36 and near[2].d-near[1].d>=0.25 then\n     marks[#marks+1]={x=x,z=z,anchor=near[1].role,flex=near[2].role,cost=near[1].d+near[2].d}\n    end\n   end\n  end\n  local best,second,chosen=math.huge,math.huge,nil\n  for a=1,#marks-2 do for b=a+1,#marks-1 do for c=b+1,#marks do\n   local tri={marks[a],marks[b],marks[c]}\n   local area=math.abs((tri[2].x-tri[1].x)*(tri[3].z-tri[1].z)-(tri[3].x-tri[1].x)*(tri[2].z-tri[1].z))\n   local used,valid,cost={},area>2,0\n   for _,m in ipairs(tri)do\n    if used[m.anchor] or used[m.flex]then valid=false end\n    used[m.anchor]=true;used[m.flex]=true;cost=cost+m.cost\n   end\n   if valid then\n    if cost<best then second=best;best=cost;chosen=tri elseif cost<second then second=cost end\n   end\n  end end end\n  if not chosen or second-best<0.25 then return nil,\"Stand in three clear anchor/flex pairs beside the triangle markers.\" end\n  table.sort(chosen,function(a,b)return a.x<b.x end)\n  if chosen[2].x-chosen[1].x<1 or chosen[3].x-chosen[2].x<1 then return nil,\"The three WB1 markers must define left, middle and right.\" end\n  local order={}\n  for _,m in ipairs(chosen)do order[#order+1]=m.anchor;order[#order+1]=m.flex end\n  return order,\"Captured closest anchor and second-closest flex at each triangle marker.\"\n end\n function p.save(text)\n  local order,normalized=p.parse(text)\n  if not order then p.message=normalized; return false end\n  local vowOrder,vowText=p.parseVow(p.vowEdit)\n  if not vowOrder then p.message=vowText; return false end\n  local autoOrder,autoText=p.parseAuto(p.autoOrderEdit)\n  if not autoOrder then p.message=autoText; return false end\n  local pairText=table.concat({p.wb1Anchors[1],p.wb1Flex[1],p.wb1Anchors[2],p.wb1Flex[2],p.wb1Anchors[3],p.wb1Flex[3]},\" \")\n  local pairsOK,pairError=p.validatePairs(pairText)\n  if not pairsOK then p.message=pairError;return false end\n  local wb2=p.validatePairs(p.wb2Edit)\n  if not wb2 then p.message=\"WB2 requires each non-tank role once.\";return false end\n  local wb2Text=table.concat(wb2,\" \")\n  local nextSettings={}\n  for k,v in pairs(p.settings) do nextSettings[k]=v end\n  nextSettings.callout_output=p.calloutOutput or \"Both\"\n  nextSettings.draw_region=p.region\n  nextSettings.regional_previous=p.previousRegionSettings\n  nextSettings.p6_vow_melee=p.vowMelee or \"M1\"\n  nextSettings.p6_hw_wall=p.hwWall or \"T1\"\n  nextSettings.p6_hw_north=p.hwNorth or \"T1\"\n  nextSettings.p6_wb1_pairs=pairText\n  nextSettings.p6_wb2_r1_north=p.wb2R1North\n  nextSettings.p6_wb2_order=wb2Text\n  nextSettings.p6_wb2_strategy=p.wb2Strategy or \"Static\"\n  nextSettings.doth_conga=normalized\n  nextSettings.doth_order_mode=p.dothMode==\"Live positions\" and \"Live positions\" or \"Configured conga\"\n  nextSettings.vow_pass_order=vowText\n  nextSettings.p6_vow_tts_mode=p.vowTTSMode\n  nextSettings.p6_akh_afah_hp=p.akhAfahHP\n  nextSettings.p6_dragon_hp_window=p.dragonHP\n  nextSettings.p4_eyes_strategy=p.eyesStrategy\n  nextSettings.p1_brightwing_cones=p.brightCones\n  nextSettings.p1_brightwing_side=p.brightSide\n  nextSettings.p1_skyblind_mode=p.skyblindMode\n  nextSettings.p3_custom_hold=p.customHold\n  nextSettings.p3_strategy=p.strategy==\"LPDU\" and \"LPDU\" or \"NAUR\"\n  nextSettings.p7_element_draws=p.elementDraws\n  nextSettings.p7_akh_strategy=p.akhStrategy==\"3-3-2\" and \"3-3-2\" or \"6-1-1\"\n  nextSettings.p7_auto_order=autoText\n  nextSettings.p7_auto_mode=p.autoMode\n  nextSettings.p6_cauterize_mt=p.cautMT\n  nextSettings.draw_arrow_style=p.arrowAppearance==\"Gradient\" and \"Gradient\" or \"Solid\"\n  nextSettings.draw_styles={}\n  for _,row in ipairs(p.styleRows) do\n   local choice=p.styles[row[1]]\n   nextSettings.draw_styles[row[1]]=choice==\"Disabled\" and \"Disabled\" or choice==\"Arrow\" and \"Arrow\" or \"Tether\"\n  end\n  local ok,err=pcall(FileSave,p.path,nextSettings)\n  local readOK,saved=pcall(FileLoad,p.path)\n  local stylesOK=readOK and type(saved)==\"table\" and type(saved.draw_styles)==\"table\"\n  if stylesOK then\n   for _,row in ipairs(p.styleRows) do\n    if saved.draw_styles[row[1]]~=nextSettings.draw_styles[row[1]] then stylesOK=false break end\n   end\n  end\n  if not ok or not readOK or (type(saved)==\"table\" and (saved.p6_wb1_pairs~=pairText or saved.p6_wb2_r1_north~=p.wb2R1North)) or type(saved)~=\"table\" or saved.draw_region~=nextSettings.draw_region or saved.doth_conga~=normalized or saved.p6_wb2_order~=wb2Text or saved.doth_order_mode~=nextSettings.doth_order_mode or saved.p7_element_draws~=nextSettings.p7_element_draws or saved.p7_akh_strategy~=nextSettings.p7_akh_strategy or saved.p7_auto_order~=autoText or saved.p7_auto_mode~=nextSettings.p7_auto_mode or saved.p6_cauterize_mt~=nextSettings.p6_cauterize_mt or saved.draw_arrow_style~=nextSettings.draw_arrow_style or not stylesOK or saved.p3_strategy~=nextSettings.p3_strategy or saved.p3_custom_hold~=nextSettings.p3_custom_hold or saved.p1_brightwing_cones~=nextSettings.p1_brightwing_cones or saved.p1_brightwing_side~=nextSettings.p1_brightwing_side or saved.p1_skyblind_mode~=nextSettings.p1_skyblind_mode or saved.p4_eyes_strategy~=nextSettings.p4_eyes_strategy or saved.vow_pass_order~=vowText or saved.p6_vow_tts_mode~=nextSettings.p6_vow_tts_mode or saved.p6_akh_afah_hp~=nextSettings.p6_akh_afah_hp or saved.p6_dragon_hp_window~=nextSettings.p6_dragon_hp_window or saved.p6_hw_wall~=nextSettings.p6_hw_wall or saved.p6_hw_north~=nextSettings.p6_hw_north or saved.p6_wb2_strategy~=nextSettings.p6_wb2_strategy or saved.p6_vow_melee~=nextSettings.p6_vow_melee then\n   p.message=\"Save failed: \"..tostring(err or saved); return false\n  end\n  p.settings=nextSettings\n  if not p.elementDraws then\n   local element=data.frog_p7_element\n   if element and element.draw then Argus.deleteTimedShape(element.draw); element.draw=nil end\n  end\n  p.autoOrderEdit=autoText\n  p.vowEdit=vowText\n  p.order,p.saved,p.edit=order,normalized,normalized\n  p.message=\"Saved.\"\n  return true\n end\n p.order,p.saved=p.parse(p.default)\n p.edit=p.saved\n p.settings={}\n if FileExists(p.path) then\n  local ok,settings=pcall(FileLoad,p.path)\n  local order,normalized\n  if ok and type(settings)==\"table\" then\n   p.settings=settings\n   order,normalized=p.parse(settings.doth_conga)\n  end\n  if order then p.order,p.saved,p.edit=order,normalized,normalized\n  else p.message=\"Invalid settings file; using defaults. Apply to repair.\" end\n else\n  local previous=data.frog_draw_settings\n  p.save(previous and previous.saved or p.default)\n end\n p.arrowAppearance=p.settings.draw_arrow_style==\"Gradient\" and \"Gradient\" or \"Solid\"\n for _,row in ipairs(p.styleRows) do\n  local styles=p.settings.draw_styles\n  local choice=type(styles)==\"table\" and styles[row[1]]\n  p.styles[row[1]]=choice==\"Disabled\" and \"Disabled\" or choice==\"Arrow\" and \"Arrow\" or \"Tether\"\n end\n local pairRoles=p.validatePairs(p.settings.p6_wb1_pairs or \"H1 R1 M1 M2 H2 R2\")\n if pairRoles then for lane=1,3 do p.wb1Anchors[lane]=pairRoles[lane*2-1];p.wb1Flex[lane]=pairRoles[lane*2] end end\n p.vowMelee=p.settings.p6_vow_melee==\"M2\" and \"M2\" or \"M1\"\n p.hwWall=p.settings.p6_hw_wall==\"T2\" and \"T2\" or \"T1\"\n p.hwNorth=p.settings.p6_hw_north==\"T2\" and \"T2\" or \"T1\"\n p.wb2Strategy=p.settings.p6_wb2_strategy==\"5-1\" and \"5-1\" or \"Static\"\n p.wb2R1North=p.settings.p6_wb2_r1_north==true\n local wb2=p.validatePairs(p.settings.p6_wb2_order or \"\")\n p.wb2Edit=wb2 and table.concat(wb2,\" \") or (p.wb2R1North and \"H1 R2 M1 M2 H2 R1\" or p.wb2Default)\n local autoOrder,autoText=p.parseAuto(p.settings.p7_auto_order or p.autoOrderDefault)\n p.autoOrderEdit=autoOrder and autoText or p.autoOrderDefault\n if not autoOrder then p.message=\"Invalid auto order; Save to use M R H.\" end\n p.elementDraws=p.settings.p7_element_draws~=false\n p.akhStrategy=p.settings.p7_akh_strategy==\"3-3-2\" and \"3-3-2\" or \"6-1-1\"\n p.autoMode=p.settings.p7_auto_mode==\"Shotcaller\" and \"Shotcaller\" or p.settings.p7_auto_mode==\"Disabled\" and \"Disabled\" or \"Personal\"\n local vowOrder,vowText=p.parseVow(p.settings.vow_pass_order or p.vowDefault)\n p.vowEdit=vowOrder and vowText or p.vowDefault\n p.akhAfahHP=p.settings.p6_akh_afah_hp==true\n p.dragonHP=p.settings.p6_dragon_hp_window~=false\n p.calloutOutput=p.settings.callout_output or \"Both\"\n p.vowTTSMode=p.settings.p6_vow_tts_mode==\"Shotcaller\" and \"Shotcaller\" or p.settings.p6_vow_tts_mode==\"Disabled\" and \"Disabled\" or \"Personal\"\n if not vowOrder then p.message=\"Invalid Vow order; Save to use T T M R.\" end\n p.strategy=p.settings.p3_strategy==\"LPDU\" and \"LPDU\" or \"NAUR\"\n p.eyesStrategy=({Square=true,Trapezoid=true,Mana=true,Elemental=true})[p.settings.p4_eyes_strategy] and p.settings.p4_eyes_strategy or \"Square\"\n p.region=p.settings.draw_region or \"NA\"\n p.previousRegionSettings=p.settings.regional_previous\n p.brightCones=p.settings.p1_brightwing_cones~=false\n p.brightSide=p.settings.p1_brightwing_side==\"Left\"and \"Left\"or p.settings.p1_brightwing_side==\"Right\"and \"Right\"or \"Roster\"\n p.skyblindMode=p.settings.p1_skyblind_mode==\"Shotcaller\"and \"Shotcaller\"or p.settings.p1_skyblind_mode==\"Disabled\"and \"Disabled\"or \"Personal\"\n p.customHold=p.settings.p3_custom_hold==true\n p.dothMode=p.settings.doth_order_mode==\"Live positions\" and \"Live positions\" or \"Configured conga\"\n for _,value in ipairs(p.cautItems) do\n  if p.settings.p6_cauterize_mt==value then p.cautMT=value; break end\n end\n local previous=data.frog_draw_settings\n if previous then\n  for _,key in ipairs({\"calloutOutput\",\"arrowAppearance\",\"region\",\"previousRegionSettings\",\"edit\",\"vowEdit\",\"autoOrderEdit\",\"elementDraws\",\"akhStrategy\",\"autoMode\",\"strategy\",\"eyesStrategy\",\"brightCones\",\"brightSide\",\"skyblindMode\",\"customHold\",\"dothMode\",\"cautMT\",\"vowTTSMode\",\"akhAfahHP\",\"dragonHP\",\"vowMelee\",\"hwWall\",\"hwNorth\",\"wb1Anchors\",\"wb1Flex\",\"wb2Strategy\",\"wb2R1North\",\"wb2Edit\",\"message\"}) do\n   if previous[key]~=nil then p[key]=previous[key] end\n  end\n  for _,row in ipairs(p.styleRows) do\n   if previous.styles and previous.styles[row[1]] then p.styles[row[1]]=previous.styles[row[1]] end\n  end\n end\n data.frog_draw_settings=p\nend\n\nlocal p=data.frog_draw_settings\nif p.strategyItems[1]~=\"Westhogg\" then\n p.strategyItems[1]=\"Westhogg\"; p.strategyItems[2]=\"Easthogg\"\nend\nif not p.ui or p.ui.version~=2 then\n local ui={version=2,scopes={\"This phase\",\"All phases\"},phases={\"P1 - Vault & Rewind\",\"P2 - Thordan\",\"P3 - Nidhogg\",\"P4 - Eyes\",\"P5 - Dark Thordan\",\"P6 - Double Dragons\",\"P7 - Dragon-King\"},regions={\"NA\",\"EU\",\"Mana\",\"Elemental\"},groups={{},{},{},{},{},{},{}},keys={},labels={}}\n ui.colors={{\"Text\",.91,.92,.90,1},{\"WindowBg\",.11,.11,.11,1},{\"Border\",.29,.31,.28,1},{\"TitleBg\",.13,.13,.13,1},{\"TitleBgActive\",.15,.15,.15,1},{\"FrameBg\",.18,.19,.18,1},{\"FrameBgHovered\",.23,.28,.23,1},{\"FrameBgActive\",.23,.32,.24,1},{\"Header\",.21,.23,.21,1},{\"HeaderHovered\",.23,.32,.23,1},{\"HeaderActive\",.29,.40,.28,1},{\"CheckMark\",.56,.76,.49,1},{\"Button\",.21,.23,.21,1},{\"ButtonHovered\",.29,.31,.28,1},{\"ButtonActive\",.34,.37,.32,1}}\n for _,row in ipairs(p.styleRows)do\n  if row[1]~=\"p6_hw_party\"and row[1]~=\"p6_hw_tank\"then\n   local phase=tonumber(row[1]:sub(2,2))\n   ui.groups[phase][#ui.groups[phase]+1]=row[1];ui.keys[#ui.keys+1]=row[1];ui.labels[row[1]]=({p1_playstation=\"PlayStation\",p1_brightwing=\"Rewind cleaves\",p2_strength=\"Strength\",p2_sanctity=\"Sanctity\",p3_dfg=\"Dive from Grace\",p3_enum=\"Enumeration\",p4_eyes=\"Eyes\",p5_wrath=\"Wrath\",p5_doth=\"DOTH\",p6_vow=\"Mortal Vow\",p6_wb1=\"Wyrmsbreath 1\",p6_wb2=\"Wyrmsbreath 2\",p6_cauterize=\"Double Cauterize\",p7_trinity=\"Trinity\",p7_akh=\"Akh Morn\",p7_giga=\"Gigaflare\"})[row[1]]\n  end\n end\n function ui.push()\n  for _,c in ipairs(ui.colors)do GUI:PushStyleColor(GUI[\"Col_\"..c[1]],c[2],c[3],c[4],c[5])end\n  GUI:PushStyleVar(GUI.StyleVar_WindowRounding,0)\n  GUI:PushStyleVar(GUI.StyleVar_FrameRounding,0)\n  GUI:PushStyleVar(GUI.StyleVar_FrameBorderSize,1)\n  GUI:PushStyleVar(GUI.StyleVar_FramePadding,5*ui.scale,3*ui.scale)\n  GUI:PushStyleVar(GUI.StyleVar_ItemSpacing,6*ui.scale,6*ui.scale)\n end\n function ui.pop()GUI:PopStyleVar(5);GUI:PopStyleColor(#ui.colors)end\n function ui.label(text)GUI:AlignFirstTextHeightToWidgets();GUI:TextUnformatted(text);GUI:SameLine(ui.column)end\n function ui.combo(label,id,index,items,width)\n  ui.label(label);GUI:PushItemWidth(width or ui.width)\n  local selected=GUI:Combo(\"##dsr.\"..id,index,items)\n  GUI:PopItemWidth();return selected\n end\n function ui.sharedMode()\n  local common\n  for _,key in ipairs(p.quickStyleScope==2 and ui.keys or ui.groups[p.phase])do\n   local mode=p.styles[key];if common and common~=mode then return nil end;common=mode\n  end\n  return common\n end\n function ui.applyPreset(region)\n   local wasJP=p.region==\"Mana\" or p.region==\"Elemental\"\n   local isJP=region==\"Mana\" or region==\"Elemental\"\n   local fields={\"edit\",\"autoOrderEdit\",\"akhStrategy\",\"vowMelee\",\"vowEdit\",\"hwWall\",\"hwNorth\",\"dothMode\",\"wb2Edit\",\"wb2R1North\"}\n   if isJP and not wasJP then\n    p.previousRegionSettings={}\n    for _,field in ipairs(fields) do p.previousRegionSettings[field]=p[field] end\n   elseif wasJP and not isJP and p.previousRegionSettings then\n    for _,field in ipairs(fields) do if p.previousRegionSettings[field]~=nil then p[field]=p.previousRegionSettings[field] end end\n    p.previousRegionSettings=nil\n   end\n   p.region=region\n   p.strategy=(region==\"EU\" or region==\"Elemental\") and \"LPDU\" or \"NAUR\"\n   p.eyesStrategy=region==\"NA\" and \"Square\" or region==\"EU\" and \"Trapezoid\" or region\n   p.wb2Strategy=(region==\"EU\" or region==\"Elemental\") and \"5-1\" or \"Static\"\n   p.cautMT=region==\"NA\" and \"Nidhogg\" or \"Fixed West\"\n   if region==\"Mana\" then\n    p.wb1Anchors={\"H1\",\"M1\",\"R2\"};p.wb1Flex={\"R1\",\"M2\",\"H2\"}\n    p.edit=\"MT OT M1 M2 R1 R2 H1 H2\"\n   elseif region==\"Elemental\" then\n    p.wb1Anchors={\"H1\",\"R2\",\"H2\"};p.wb1Flex={\"M1\",\"R1\",\"M2\"}\n    p.edit=\"MT OT H1 H2 M1 M2 R1 R2\"\n   elseif region==\"EU\" then\n    p.wb1Anchors={\"H1\",\"M1\",\"R1\"};p.wb1Flex={\"H2\",\"M2\",\"R2\"}\n   else\n    p.wb1Anchors={\"H1\",\"M1\",\"H2\"};p.wb1Flex={\"R1\",\"M2\",\"R2\"}\n   end\n   if region==\"Mana\" or region==\"Elemental\" then\n    p.autoOrderEdit=region==\"Mana\" and \"H M R\" or \"M R H\"\n    p.akhStrategy=\"3-3-2\";p.vowEdit=\"T T M R\";p.vowMelee=\"M1\"\n    p.hwWall=\"T1\";p.hwNorth=\"T1\";p.dothMode=\"Configured conga\"\n    p.wb2Edit=p.wb2Default;p.wb2R1North=false\n   end\n   p.message=region..\" preset. Save to apply.\"\n end\n p.ui=ui\nend\nlocal ui=p.ui\nui.scale=math.max(1,GUI:GetWindowFontSize()/14);ui.column=146*ui.scale;ui.width=246*ui.scale\np.phase=p.phase or 1;p.quickStyleScope=p.quickStyleScope or 1\nif not p.presetChoice then p.presetChoice=1;for i,region in ipairs(ui.regions)do if p.region==region then p.presetChoice=i end end end\nGUI:SetNextWindowSize(410*ui.scale,470*ui.scale,GUI.SetCond_FirstUseEver)\nui.push()\nlocal visible=GUI:Begin(\"Frog / DSR Draws\",nil,GUI.WindowFlags_AlwaysAutoResize)\nif visible then\n if timelineMenu then pref.draw();GUI:Separator()end\n p.phase=ui.combo(\"Phase\",\"phase\",p.phase,ui.phases)\n p.presetChoice=ui.combo(\"Preset\",\"preset\",p.presetChoice,ui.regions,174*ui.scale)\n GUI:SameLine(ui.column+180*ui.scale)\n if GUI:Button(\"Apply##dsr.preset\",66*ui.scale,22*ui.scale)then ui.applyPreset(ui.regions[p.presetChoice])end\n if GUI:IsItemHovered()then GUI:SetTooltip(\"Use these preset defaults, then Save settings to apply.\")end\n GUI:PushStyleColor(GUI.Col_Text,.62,.69,.61,1);GUI:TextUnformatted(\"Active preset: \"..p.region);GUI:PopStyleColor(1)\n GUI:Separator()\n if GUI:Button(\"Open AnyoneCore roster\")then\n  local popup=AnyoneCore and AnyoneCore.RosterPopup\n  if popup and type(popup.openManual)==\"function\"then\n   local ok,err=pcall(popup.openManual);if not ok then p.message=\"Roster could not open: \"..tostring(err)end\n  else p.message=\"AnyoneCore roster is unavailable\"end\n end\n GUI:Separator()\n ui.label(\"Quick style\")\n local common=ui.sharedMode()\n for i,mode in ipairs(p.styleItems)do\n  if i>1 then GUI:SameLine(ui.column+(i-1)*84*ui.scale)end\n  local selected=common==mode\n  if selected then GUI:PushStyleColor(GUI.Col_Button,.29,.40,.28,1)end\n  local pressed=GUI:Button(mode..\"##dsr.quick_style\",78*ui.scale,22*ui.scale)\n  if selected then GUI:PopStyleColor(1)end\n  if pressed then\n   for _,key in ipairs(p.quickStyleScope==2 and ui.keys or ui.groups[p.phase])do p.styles[key]=mode end\n   p.message=(p.quickStyleScope==2 and \"All phases: \"or\"This phase: \")..mode..\" / unsaved\"\n  end\n end\n local arrowVisible=false\n for _,row in ipairs(p.styleRows)do\n  if (p.quickStyleScope==2 or row[1]:match(\"^p\"..p.phase..\"_\"))and p.styles[row[1]]==\"Arrow\"then arrowVisible=true;break end\n end\n if arrowVisible then\n  local appearances={\"Solid\",\"Gradient\"}\n  local appearance=appearances[ui.combo(\"Arrow appearance\",\"arrow_appearance\",p.arrowAppearance==\"Gradient\"and 2 or 1,appearances)]\n  if appearance~=p.arrowAppearance then p.arrowAppearance=appearance;p.message=\"Unsaved changes\"end\n end\n p.quickStyleScope=ui.combo(\"Style scope\",\"style_scope\",p.quickStyleScope,ui.scopes)\n local outputValues={\"Both\",\"Text only\",\"Sound only\",\"Neither\"}\n local outputIndex=1;for i,value in ipairs(outputValues)do if value==p.calloutOutput then outputIndex=i end end\n local output=outputValues[ui.combo(\"Callouts\",\"callouts\",outputIndex,{\"Both\",\"Text only\",\"Sound only\",\"Off\"})]\n if output~=p.calloutOutput then p.calloutOutput=output;p.message=\"Unsaved changes\"end\n if GUI:IsItemHovered()then GUI:SetTooltip(\"Text, voice, both or off. Save settings to apply.\")end\n GUI:Separator()\n local function changed(field,value)\n  if value~=nil and value~=p[field] then p[field]=value; p.message=\"Unsaved changes\" end\n end\n local function choice(id,label,index,items)\n  return ui.combo(label,id,index,items)\n end\n local function style(key,label)\n  local value=p.styles[key]\n  local index=value==\"Disabled\" and 3 or value==\"Arrow\" and 2 or 1\n  local selected=choice(key,label,index,p.styleItems)\n  local valueNew=p.styleItems[selected]\n  if valueNew and valueNew~=value then p.styles[key]=valueNew; p.message=\"Unsaved changes\" end\n end\n\n local function order(field,id,label,default)\n  ui.label(label)\n  GUI:PushItemWidth(ui.width-64*ui.scale)\n  changed(field,GUI:InputText(\"##dsr.\"..id,p[field]))\n  GUI:PopItemWidth()\n  GUI:SameLine(ui.column+ui.width-58*ui.scale)\n  if GUI:Button(\"Reset##dsr.\"..id,58*ui.scale,22*ui.scale)then changed(field,default)end\n end\n local function lineup(id,text,defaults,valid)\n  p.lineupWidgets=p.lineupWidgets or {}\n  local w=p.lineupWidgets[id]\n  if not w or w.text~=text then\n   local values=valid(text)\n   if not values then values=valid(defaults)end\n   w={text=text,values=values};p.lineupWidgets[id]=w\n  end\n  local captured=false;local changedOrder=false;local note\n  if GUI:Button(\"Capture lineup##\"..id)then\n   local expected=valid(defaults)\n   local values,message\n   if id==\"wb1\"then values,message=p.captureWB1()elseif id==\"doth\"then values,message=p.captureDOTH()else values,message=p.captureLineup(expected)end\n   if values then w.values=values;captured=true;changedOrder=true;note=message else p.message=message end\n  end\n  if GUI:IsItemHovered()then GUI:SetTooltip(\"Capture the live lineup. DOTH: west to east. Drag onto a box centre to swap; use its left/right edge to insert before/after.\")end\n  GUI:SameLine()\n  if GUI:Button(\"Reverse##\"..id)then\n   local values=w.values\n   for i=1,math.floor(#values/2)do values[i],values[#values-i+1]=values[#values-i+1],values[i]end\n   changedOrder=true\n  end\n  local drop\n  for i,role in ipairs(w.values)do\n   local label=role\n   local width=36\n   if id==\"wb1\"then\n    if i%2==1 then\n     GUI:Separator()\n     GUI:TextUnformatted(({\"Left pair\",\"Middle pair\",\"Right pair\"})[math.floor((i+1)/2)])\n    else GUI:SameLine()end\n    label=(i%2==1 and \"Anchor: \" or \"Flex: \")..role\n    width=110\n   elseif id==\"wb2\"then\n    if i%2==1 then GUI:Separator()else GUI:SameLine()end\n    label=({\"North wall: \",\"SW outer: \",\"SW inner: \",\"NE inner: \",\"South wall: \",\"NE outer: \"})[i]..role\n    width=145\n   elseif i>1 then GUI:SameLine()end\n   GUI:Button(label..\"##\"..id..\"_\"..role,width*ui.scale,26*ui.scale)\n   if GUI:IsItemClicked(0)then p.lineupDrag={id=id,index=i}end\n   local ax,ay=GUI:GetItemRectMin();local bx,by=GUI:GetItemRectMax()\n   if p.lineupDrag and p.lineupDrag.id==id and GUI:IsMouseHoveringRect(ax,ay,bx,by,true)then\n    drop=i\n    local mx=GUI:GetMousePos()\n    local fraction=(mx-ax)/math.max(1,bx-ax)\n    p.lineupDropMode=fraction<0.25 and \"before\" or fraction>0.75 and \"after\" or \"swap\"\n    GUI:SetTooltip(p.lineupDropMode==\"swap\" and \"Swap with \"..role or (p.lineupDropMode==\"before\" and \"Insert before \" or \"Insert after \")..role)\n   end\n  end\n  if p.lineupDrag and p.lineupDrag.id==id and GUI:IsMouseReleased(0)then\n   local from=p.lineupDrag.index\n   if drop and drop~=from then\n    if p.lineupDropMode==\"swap\"then\n     w.values[from],w.values[drop]=w.values[drop],w.values[from]\n     changedOrder=true\n    else\n     local slot=drop+(p.lineupDropMode==\"after\" and 1 or 0)\n     if from<slot then slot=slot-1 end\n     if slot~=from then table.insert(w.values,slot,table.remove(w.values,from));changedOrder=true end\n    end\n   end\n   p.lineupDrag=nil;p.lineupDropMode=nil\n  end\n  if changedOrder then\n   w.text=table.concat(w.values,\" \")\n   p.message=note or \"Unsaved changes\"\n   return w.text,captured,note\n  end\n  return text,false\n end\n if GUI:CollapsingHeader(\"Individual mechanic styles##dsr.\"..p.phase)then\n  for _,key in ipairs(ui.groups[p.phase])do style(key,ui.labels[key])end\n  GUI:Spacing();GUI:Separator();GUI:Spacing()\n end\n GUI:PushItemWidth(145)\n\n if p.phase==1 then\n   local selected=choice(\"p1_brightwing_cones\",\"Brightwing cones\",p.brightCones and 1 or 2,p.holdItems)\n   changed(\"brightCones\",selected==1)\n   selected=choice(\"p1_brightwing_side\",\"Brightwing side\",p.brightSide==\"Left\"and 2 or p.brightSide==\"Right\"and 3 or 1,{\"Roster\",\"Left\",\"Right\"})\n   changed(\"brightSide\",({\"Roster\",\"Left\",\"Right\"})[selected])\n   selected=choice(\"p1_skyblind_mode\",\"Skyblind callout\",p.skyblindMode==\"Shotcaller\"and 2 or p.skyblindMode==\"Disabled\"and 3 or 1,p.autoModeItems)\n   changed(\"skyblindMode\",p.autoModeItems[selected])\n end\n if p.phase==2 then\n end\n if p.phase==3 then\n  local selected=choice(\"p3_strategy\",\"Strategy\",p.strategy==\"LPDU\" and 2 or 1,p.strategyItems)\n  changed(\"strategy\",selected==2 and \"LPDU\" or \"NAUR\")\n  selected=choice(\"p3_custom_hold\",\"Lock face + stop\",p.customHold and 1 or 2,p.holdItems)\n  changed(\"customHold\",selected==1)\n end\n if p.phase==4 then\n   local values={\"Square\",\"Trapezoid\",\"Mana\",\"Elemental\"}\n   local index=1;for i,v in ipairs(values) do if p.eyesStrategy==v then index=i end end\n   local selected=choice(\"p4_eyes_strategy\",\"Eyes strategy\",index,{\"NAUR\",\"LPDU\",\"Tuufless (Mana)\",\"Tuufless (Elemental)\"})\n   changed(\"eyesStrategy\",values[selected])\n   if p.eyesStrategy==\"Trapezoid\" then GUI:TextUnformatted(\"North to south / G1 north / G2 south\") end\n end\n if p.phase==5 then\n  local selected=choice(\"doth_order_mode\",\"DOTH order\",p.dothMode==\"Live positions\" and 2 or 1,p.dothModeItems)\n  changed(\"dothMode\",p.dothModeItems[selected])\n  GUI:TextUnformatted(\"DOTH order - drag to rearrange\")\n  local value,captured,note=lineup(\"doth\",p.edit,p.default,p.parse)\n  if value~=p.edit then p.dothMode=\"Configured conga\" end\n  changed(\"edit\",value)\n  if captured then p.dothMode=\"Configured conga\";if p.save(p.edit)then p.message=note..\" Saved.\"end end\n end\n if p.phase==6 then\n  local dragonHP=choice(\"p6_dragon_hp_window\",\"Dragon HP window\",p.dragonHP and 1 or 2,p.holdItems)\n  changed(\"dragonHP\",dragonHP==1)\n  local afahHP=choice(\"p6_akh_afah_hp\",\"Afah HP callout\",p.akhAfahHP and 1 or 2,p.holdItems)\n  changed(\"akhAfahHP\",afahHP==1)\n  local melee=choice(\"p6_vow_melee\",\"Vow melee pass\",p.vowMelee==\"M2\" and 2 or 1,{\"M1\",\"M2\"})\n  changed(\"vowMelee\",melee==2 and \"M2\" or \"M1\")\n  local vowMode=choice(\"p6_vow_tts_mode\",\"Vow callouts\",p.vowTTSMode==\"Personal\" and 1 or p.vowTTSMode==\"Disabled\" and 3 or 2,p.autoModeItems)\n  changed(\"vowTTSMode\",p.autoModeItems[vowMode])\n  if p.styles.p6_vow~=\"Disabled\" then\n   order(\"vowEdit\",\"vow_order\",\"Vow pass order\",p.vowDefault)\n  end\n  local me=TensorCore.mGetPlayer()\n  local isTank=me and (me.job==19 or me.job==21 or me.job==32 or me.job==37)\n  if isTank then\n   local enabled=choice(\"p6_hw_tank\",\"Tank Wings\",p.styles.p6_hw_tank==\"Disabled\" and 2 or 1,{\"On\",\"Off\"})\n   p.styles.p6_hw_tank=enabled==2 and \"Disabled\" or \"Tether\"\n   local tankItems={\"MT\",\"OT\"}\n   local north=choice(\"p6_hw_north\",\"Wings 1 north\",p.hwNorth==\"T2\" and 2 or 1,tankItems)\n   changed(\"hwNorth\",north==2 and \"T2\" or \"T1\")\n   local wall=choice(\"p6_hw_wall\",\"Wings 2 wall\",p.hwWall==\"T2\" and 2 or 1,tankItems)\n   changed(\"hwWall\",wall==2 and \"T2\" or \"T1\")\n  else\n   local enabled=choice(\"p6_hw_party\",\"Party Wings\",p.styles.p6_hw_party==\"Disabled\" and 2 or 1,{\"On\",\"Off\"})\n   p.styles.p6_hw_party=enabled==2 and \"Disabled\" or \"Arrow\"\n  end\n  GUI:TextUnformatted(\"WB1 pairs - anchor stays, flex adjusts\")\n  local pairsText=table.concat({p.wb1Anchors[1],p.wb1Flex[1],p.wb1Anchors[2],p.wb1Flex[2],p.wb1Anchors[3],p.wb1Flex[3]},\" \")\n  local value,captured,note=lineup(\"wb1\",pairsText,\"H1 R1 M1 M2 H2 R2\",p.validatePairs)\n  if value~=pairsText then\n   local roles=p.validatePairs(value)\n   for i=1,3 do p.wb1Anchors[i]=roles[i*2-1];p.wb1Flex[i]=roles[i*2]end\n   p.message=\"Unsaved changes\"\n  end\n  if captured and p.save(p.edit)then p.message=note..\" Saved.\"end\n  GUI:TextUnformatted(\"Anchors hold; flexers match opposite colours.\")\n  local strat=choice(\"p6_wb2_strategy\",\"WB2 strategy\",p.wb2Strategy==\"5-1\" and 2 or 1,{\"Static\",\"5-1\"})\n  changed(\"wb2Strategy\",strat==2 and \"5-1\" or \"Static\")\n  if p.wb2Strategy==\"Static\" then\n  GUI:TextUnformatted(\"WB2 fixed spots - drag roles between labelled positions\")\n  local value,captured,note=lineup(\"wb2\",p.wb2Edit,p.wb2Default,p.validatePairs)\n  changed(\"wb2Edit\",value)\n  if captured and p.save(p.edit)then p.message=note..\" Saved.\"end\n  else\n   GUI:TextUnformatted(\"North W-E: M1 R1 H2 R2 M2 | South: H1\")\n  end\n  if p.styles.p6_cauterize~=\"Disabled\" then\n   local index=1\n   for i,value in ipairs(p.cautItems) do if value==p.cautMT then index=i; break end end\n   local selected=choice(\"p6_cauterize_mt\",\"MT takes\",index,p.cautItems)\n   changed(\"cautMT\",p.cautItems[selected])\n   GUI:TextUnformatted(\"OT takes: \"..p.cautOpposite[selected])\n  end\n end\n if p.phase==7 then\n  if p.styles.p7_akh~=\"Disabled\" then\n   local selected=choice(\"p7_akh_strategy\",\"Akh Morn groups\",p.akhStrategy==\"3-3-2\" and 2 or 1,p.akhStrategyItems)\n   changed(\"akhStrategy\",p.akhStrategyItems[selected])\n   if p.akhStrategy==\"3-3-2\" then GUI:TextUnformatted(\"G1 NW / G2 NE / tanks S\") end\n  end\n  local selected=choice(\"p7_element_draws\",\"Flames / ice\",p.elementDraws and 1 or 2,p.holdItems)\n  changed(\"elementDraws\",selected==1)\n  selected=choice(\"p7_auto_mode\",\"Auto callouts\",p.autoMode==\"Shotcaller\" and 2 or p.autoMode==\"Disabled\" and 3 or 1,p.autoModeItems)\n  changed(\"autoMode\",p.autoModeItems[selected])\n  if p.autoMode~=\"Disabled\" then\n   ui.label(\"Auto priority\")\n   GUI:PushItemWidth(ui.width)\n   changed(\"autoOrderEdit\",GUI:InputText(\"##dsr.p7_auto_order\",p.autoOrderEdit))\n   GUI:PopItemWidth()\n   if GUI:IsItemHovered()then GUI:SetTooltip(\"M: melee, R: ranged, H: healers. Group 1 first.\")end\n   local valid,err=p.parseAuto(p.autoOrderEdit)\n   if not valid then GUI:TextUnformatted(err) end\n  end\n end\n GUI:PopItemWidth()\n GUI:Separator()\n if GUI:Button(\"Save settings\",122*ui.scale,24*ui.scale)then p.save(p.edit)end\n if p.message then GUI:SameLine();GUI:TextUnformatted(p.message)end\nend\nGUI:End()\nui.pop()\nself.used=true\n\n end\n FrogDrawMenuHost=h\nend\nlocal now=os.time()\nif now-h.lastSeen>2 then h.owners={}end\nh.lastSeen=now\nself.used=true\n\nlocal h=FrogDrawMenuHost\nlocal pref=FrogDrawMenuPreferences\nif not h or h.protocolVersion~=2 or os.time()-h.lastSeen>2 then self.used=true return end\nif not pref.inDuty()then\n local visible=GUI:Begin(\"Frog / Draw settings\",nil,GUI.WindowFlags_AlwaysAutoResize)\n if visible then\n  if GUI:Button(\"FRU settings\")and pref.selected~=\"fru\"then pref.selected=\"fru\";pref.save()end\n  GUI:SameLine()\n  if GUI:Button(\"DSR settings\")and pref.selected~=\"dsr\"then pref.selected=\"dsr\";pref.save()end\n  pref.draw()\n end\n GUI:End()\n local game=pref.selected\n if h.claim(game,\"general\")then\n  if game==\"fru\"then h.reloadFRU();h.fruData={}else h.dsrData={}end\n end\n if game==\"fru\"then\n  h.fruData=h.fruData or {};h.renderFRU(h.fruData);h.settings.fru=FrogFRUDrawSettings\n else\n  h.dsrData=h.dsrData or {};h.renderDSR(h.dsrData);h.settings.dsr=h.dsrData.frog_draw_settings\n end\nend\nh.lastDraw=os.time()\nself.used=true\n",
